head.script:
//
const path = window.location.pathname;
if (path === '/' || path.includes('/sessions')) {
  document.documentElement.classList.add('app-mode');
} else {
  document.documentElement.classList.add('blog-mode');
}
//

head.b:skin:
/* --- CSS RESET & VARIABLES --- */
:root {
  --bg-color: #fcfcfc;
  --text-color: #1a1a1a;
  --accent-color: #333333;
  --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
*, *::before, *::after { box-sizing: border-box; }
body { margin: 0; padding: 0; font-family: var(--font-main); background: var(--bg-color); color: var(--text-color); -webkit-font-smoothing: antialiased; }
a { text-decoration: none; color: var(--text-color); }

/* --- TWO-TIER HEADER & SEARCH --- */
.site-header { display: flex; flex-direction: column; background: var(--bg-color); position: sticky; top: 0; z-index: 1000; border-bottom: 1px solid #eaeaea; transition: background 0.3s; }
.header-top { display: flex; justify-content: space-between; align-items: center; padding: 25px 50px; border-bottom: 1px solid rgba(0,0,0,0.05); }
.site-title { font-size: 28px; font-weight: 800; letter-spacing: -0.5px; }
.header-search { display: flex; align-items: center; width: 100%; max-width: 320px; }
.header-search input { width: 100%; padding: 10px 15px; border: 1px solid #e0e0e0; border-right: none; border-radius: 4px 0 0 4px; font-size: 14px; outline: none; font-family: var(--font-main); background: #f9f9f9; }
.header-search button { padding: 10px 20px; background: var(--text-color); color: var(--bg-color); border: none; border-radius: 0 4px 4px 0; cursor: pointer; font-weight: 600; font-size: 14px; font-family: var(--font-main); }

.header-bottom { display: flex; justify-content: center; padding: 15px 50px; }
.site-nav { display: flex; gap: 30px; align-items: center; flex-wrap: wrap; justify-content: center; }
.site-nav a { font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; color: #555; transition: color 0.2s; }
.site-nav a:hover { color: #000; }
.timer-link { background: var(--text-color); color: var(--bg-color) !important; padding: 8px 16px; border-radius: 4px; }

/* --- HOMEPAGE GRID (DEPOSITORY) --- */
.status-header { text-align: center; padding: 40px 20px 0; font-size: 22px; font-weight: 600; color: #333; }
.grid-container { display: grid; grid-template-columns: repeat(auto-fill, minmax(350px, 1fr)); gap: 30px; padding: 50px; max-width: 1600px; margin: 0 auto; min-height: 50vh; }
.video-card { position: relative; aspect-ratio: 16/9; overflow: hidden; border-radius: 8px; background: #eee; cursor: pointer; }
.video-card img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s ease; }
.video-card:hover img { transform: scale(1.05); }
.card-overlay { position: absolute; inset: 0; background: rgba(0,0,0,0.6); opacity: 0; transition: opacity 0.3s ease; display: flex; flex-direction: column; justify-content: flex-end; padding: 25px; }
.video-card:hover .card-overlay { opacity: 1; }
.card-tags { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 10px; }
.tag { background: rgba(255,255,255,0.2); color: #fff; padding: 4px 10px; border-radius: 4px; font-size: 11px; font-weight: 600; text-transform: uppercase; backdrop-filter: blur(4px); }
.card-title { color: #fff; font-size: 18px; font-weight: 600; margin: 0; }

/* --- STATIC PAGE LAYOUT --- */
.page-container { padding: 60px 20px; max-width: 800px; margin: 0 auto; min-height: 50vh; }
.page-container h1 { font-size: 36px; margin-bottom: 30px; letter-spacing: -0.5px; border-bottom: 2px solid #eaeaea; padding-bottom: 15px; }
.page-body { font-size: 16px; line-height: 1.8; color: #444; }

/* --- FIXED PAGINATION --- */
.blog-pager { text-align: center; padding: 20px 50px 60px; display: flex; justify-content: center; gap: 15px; }
.blog-pager a { padding: 12px 24px; background: var(--text-color); color: var(--bg-color); border-radius: 4px; font-weight: 700; font-size: 14px; text-transform: uppercase; letter-spacing: 1px; }
.blog-pager a:hover { background: #444; }

/* --- FOOTER --- */
.site-footer { position: relative; z-index: 10; background: #1a1a1a; color: #eeeeee; padding: 60px 50px 30px; margin-top: 0; border-top: 1px solid rgba(255,255,255,0.1); }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 40px; max-width: 1200px; margin: 0 auto; }
.footer-col h4 { color: #ffffff; font-size: 16px; margin-bottom: 20px; text-transform: uppercase; }
.footer-links { list-style: none; padding: 0; margin: 0; }
.footer-links li { margin-bottom: 12px; }
.footer-links a { color: #bbbbbb; font-size: 14px; }
.footer-links a:hover { color: #ffffff; }
.footer-bottom { text-align: center; padding-top: 30px; margin-top: 40px; border-top: 1px solid #333; font-size: 12px; color: #777; }

/* --- NUCLEAR HIDE --- */
.widget, .sidebar, .post-footer, .comments, .fauxcolumn-outer { display: none !important; }
.widget.Blog, .site-header, .site-footer, .main { display: block !important; }

/* --- THEATER MODE --- */
.single-post-view { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; background: #000; z-index: 9999; display: flex; justify-content: center; align-items: center; flex-direction: column; }
.close-btn { position: absolute; top: 30px; right: 40px; color: #fff; font-size: 40px; cursor: pointer; z-index: 10000; }
.video-wrapper { width: 90%; max-width: 1400px; aspect-ratio: 16/9; position: relative; }
.video-wrapper iframe { position: absolute; top: 0; left: 0; width: 100%; height: 100%; border: none; border-radius: 8px; }

@media (max-width: 768px) {
  .header-top { flex-direction: column; padding: 20px; text-align: center; }
  .header-search { max-width: 100%; }
  .grid-container { grid-template-columns: 1fr; padding: 20px; }
  .site-footer { padding: 40px 20px; }
}

/* --- SESSIONS APP STYLES --- */
.sessions-app-container { position: relative; width: 100%; min-height: calc(100vh - 140px); justify-content: center; align-items: center; font-family: var(--font-main); padding: 40px 20px; }

.sessions-bg { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background-color: #2c3e50; background-image: url('https://images.pexels.com/photos/1624496/pexels-photo-1624496.jpeg?auto=compress&cs=tinysrgb&w=1600'); background-size: cover; background-position: center; transition: background-image 0.5s ease; z-index: -2; }
.sessions-bg::after { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.35); z-index: -1; }

.ui-glass-panel { background: rgba(255, 255, 255, 0.15); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); border: 1px solid rgba(255,255,255,0.2); padding: 30px; border-radius: 16px; width: 100%; max-width: 900px; display: grid; grid-template-columns: 1fr 1fr; gap: 20px; box-shadow: 0 15px 35px rgba(0,0,0,0.2); z-index: 5; margin-bottom: 40px; }
.widget-box { background: rgba(25, 25, 25, 0.6); color: white; padding: 25px; border-radius: 12px; }
.widget-box h3 { margin-top: 0; font-size: 18px; margin-bottom: 15px; border-bottom: 1px solid rgba(255,255,255,0.2); padding-bottom: 8px; letter-spacing: 0.5px; }

.timer-widget { grid-column: span 2; text-align: center; }
.affirmation-text { font-size: 15px; font-style: italic; color: #ffeb3b; min-height: 22px; margin-bottom: 10px; font-weight: 500; transition: opacity 0.5s ease; opacity: 1; }
.time-display { font-size: 80px; font-weight: 800; letter-spacing: 2px; margin: 0 0 10px 0; font-family: monospace; }

.timer-modes { display: flex; justify-content: center; align-items: center; gap: 5px; margin-bottom: 15px; flex-wrap: wrap; }
.timer-modes button, .timer-controls button, .bg-widget button { background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.2); color: white; padding: 8px 16px; border-radius: 20px; cursor: pointer; transition: 0.2s; font-family: var(--font-main); font-weight: 600;}
.timer-modes button:hover, .timer-controls button:hover, .bg-widget button:hover { background: rgba(255,255,255,0.3); }
.timer-modes button.settings-btn { padding: 8px 12px; font-size: 16px; border-radius: 50%; }
#startBtn { background: #4CAF50; border: none; font-weight: bold; }

.timer-settings { background: rgba(0,0,0,0.3); padding: 15px; border-radius: 10px; margin-bottom: 15px; flex-direction: column; gap: 10px; }
.timer-settings label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; align-items: center; gap: 5px; color: #fff; }
.timer-settings input { width: 60px; padding: 5px; text-align: center; border: none; border-radius: 4px; outline: none; font-family: var(--font-main); font-weight: bold; color: #333; }
.timer-settings button { background: #fff; color: #333; padding: 8px 15px; font-weight: bold; border-radius: 4px; border: none; cursor: pointer; width: 100%; transition: 0.2s; }
.timer-settings button:hover { background: #eee; }

/* Task Widget */
.task-input { display: flex; gap: 5px; margin-bottom: 15px; }
.task-input select { background: rgba(255,255,255,0.9); border: none; border-radius: 4px; padding: 8px; font-weight: bold; color: #333; outline: none; }
.task-input input { flex: 1; padding: 8px; border-radius: 4px; border: none; background: rgba(255,255,255,0.9); outline: none; font-family: var(--font-main); color: #333; }
.task-input button { background: #fff; color: #333; font-weight: bold; border: none; border-radius: 4px; padding: 8px 15px; cursor: pointer; font-family: var(--font-main); }

.task-list { list-style: none; padding: 0; margin: 0; max-height: 150px; overflow-y: auto; }
.task-list li { background: rgba(0,0,0,0.4); margin-bottom: 5px; padding: 10px 12px; border-radius: 4px; display: flex; justify-content: space-between; align-items: center; font-size: 14px; gap: 10px; }
.task-priority { font-weight: bold; color: #ffeb3b; width: 25px; display: inline-block; text-align: center; }
.task-text { flex: 1; word-break: break-word; }
.task-check { cursor: pointer; transform: scale(1.2); margin-left: 10px; }
.task-delete { background: none; border: none; color: #ff7777; font-weight: bold; cursor: pointer; font-size: 16px; padding: 0 5px; transition: color 0.2s; }
.task-delete:hover { color: #ff0000; }

/* Notepad Widget */
.notepad-widget textarea { width: 100%; height: 150px; background: rgba(255,255,255,0.9); border: none; border-radius: 4px; padding: 12px; font-family: var(--font-main); font-size: 14px; resize: vertical; outline: none; color: #333; }

/* Audio Widget */
.audio-widget select { width: 100%; padding: 10px; border-radius: 4px; border: none; background: rgba(255,255,255,0.9); margin-bottom: 15px; outline: none; font-family: var(--font-main); color: #333; font-weight: bold; }
.audio-controls { display: flex; align-items: center; gap: 15px; }
.audio-controls button { background: #fff; color: #333; font-weight: bold; border: none; border-radius: 4px; padding: 8px 15px; cursor: pointer; font-family: var(--font-main); }

.bg-widget { display: flex; align-items: center; justify-content: center; }
.bg-widget button { width: 100%; padding: 15px; font-size: 16px; background: rgba(255,255,255,0.2); backdrop-filter: blur(4px); border: 1px solid rgba(255,255,255,0.3); font-weight: 600; }

.mascot-container { position: absolute; bottom: 30px; right: 50px; z-index: 10; animation: float 6s ease-in-out infinite; }
.emoji-mascot { font-size: 80px; filter: drop-shadow(0 10px 15px rgba(0,0,0,0.4)); user-select: none; }

@keyframes float {
  0% { transform: translateY(0px) rotate(0deg); }
  50% { transform: translateY(-15px) rotate(5deg); }
  100% { transform: translateY(0px) rotate(0deg); }
}

@media (max-width: 768px) {
  .ui-glass-panel { grid-template-columns: 1fr; }
  .timer-widget { grid-column: span 1; }
  .mascot-container { display: none; }
}

b:if.script:
//
  document.addEventListener("DOMContentLoaded", function() {
    var iframes = document.querySelectorAll(".video-wrapper iframe");
    iframes.forEach(function(iframe) {
      var src = iframe.getAttribute("src");
      if (src && src.indexOf("youtube.com") !== -1 && src.indexOf("autoplay=1") === -1) {
        var separator = src.indexOf("?") !== -1 ? "&" : "?";
        iframe.setAttribute("src", src + separator + "autoplay=1");
      }
    });
  });
//

body.script:
//
  if(document.getElementById('sessionsApp')) {

    // Load Settings from Memory
    let pomoDuration = parseInt(localStorage.getItem('ll_pomo')) || 25;
    let shortDuration = parseInt(localStorage.getItem('ll_short')) || 5;
    let longDuration = parseInt(localStorage.getItem('ll_long')) || 15;
    let isAutoFlow = localStorage.getItem('ll_auto') === 'true';
    let currentAlarm = localStorage.getItem('ll_alarm') || 'chime';

    // Initialize Inputs
    document.getElementById('pomoInput').value = pomoDuration;
    document.getElementById('shortInput').value = shortDuration;
    document.getElementById('longInput').value = longDuration;
    document.getElementById('autoFlowToggle').checked = isAutoFlow;
    document.getElementById('alarmSelect').value = currentAlarm;

    let currentPreset = "pomo";
    let timerInterval;
    let timeLeft = pomoDuration * 60;
    let isRunning = false;
    let sessionsCompleted = 0;

    function updateDisplay() {
      const minutes = Math.floor(timeLeft / 60);
      const seconds = timeLeft % 60;
      document.getElementById('timeDisplay').innerText =
        `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    }

    function applyPreset(type) {
      currentPreset = type;
      clearInterval(timerInterval);
      isRunning = false;
      document.getElementById('startBtn').innerText = 'Start';

      if(type === 'pomo') timeLeft = pomoDuration * 60;
      if(type === 'short') timeLeft = shortDuration * 60;
      if(type === 'long') timeLeft = longDuration * 60;

      updateDisplay();
    }

    // NATIVE WEB AUDIO ALARMS
    function playAlarm() {
      if(currentAlarm === 'none') return;
      const ctx = new (window.AudioContext || window.webkitAudioContext)();

      if(currentAlarm === 'chime') {
        const osc1 = ctx.createOscillator();
        const osc2 = ctx.createOscillator();
        const gainNode = ctx.createGain();
        osc1.connect(gainNode);
        osc2.connect(gainNode);
        gainNode.connect(ctx.destination);

        osc1.type = 'sine'; osc2.type = 'sine';
        osc1.frequency.setValueAtTime(523.25, ctx.currentTime);
        osc2.frequency.setValueAtTime(659.25, ctx.currentTime);

        gainNode.gain.setValueAtTime(0, ctx.currentTime);
        gainNode.gain.linearRampToValueAtTime(0.5, ctx.currentTime + 0.1);
        gainNode.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 2);

        osc1.start(ctx.currentTime); osc2.start(ctx.currentTime);
        osc1.stop(ctx.currentTime + 2.5); osc2.stop(ctx.currentTime + 2.5);
      } else if (currentAlarm === 'beep') {
        let startTime = ctx.currentTime;
        for(let i=0; i<3; i++) {
          const osc = ctx.createOscillator();
          const gainNode = ctx.createGain();
          osc.connect(gainNode);
          gainNode.connect(ctx.destination);
          osc.type = 'square';
          osc.frequency.setValueAtTime(800, startTime);
          gainNode.gain.setValueAtTime(0.1, startTime);
          gainNode.gain.setValueAtTime(0, startTime + 0.15);
          osc.start(startTime);
          osc.stop(startTime + 0.15);
          startTime += 0.25;
        }
      }
    }

    function toggleTimer() {
      if (isRunning) {
        clearInterval(timerInterval);
        document.getElementById('startBtn').innerText = 'Resume';
      } else {
        timerInterval = setInterval(() => {
          if (timeLeft > 0) {
            timeLeft--;
            updateDisplay();
          } else {
            clearInterval(timerInterval);
            playAlarm();

            if(currentPreset === 'pomo') {
              sessionsCompleted++;
              document.getElementById('sessionCount').innerText = sessionsCompleted;
            }

            // Auto-Flow Logic
            if(isAutoFlow) {
              if(currentPreset === 'pomo') {
                applyPreset(sessionsCompleted > 0 && sessionsCompleted % 4 === 0 ? 'long' : 'short');
              } else {
                applyPreset('pomo');
              }
              toggleTimer();
            } else {
              document.getElementById('startBtn').innerText = 'Start';
            }

          }
        }, 1000);
        document.getElementById('startBtn').innerText = 'Pause';
      }
      isRunning = !isRunning;
    }

    function resetTimer() { applyPreset(currentPreset); }

    function toggleSettings() {
      const panel = document.getElementById('timerSettings');
      panel.style.display = panel.style.display === 'none' ? 'flex' : 'none';
    }

    function saveTimerSettings() {
      pomoDuration = parseInt(document.getElementById('pomoInput').value) || 25;
      shortDuration = parseInt(document.getElementById('shortInput').value) || 5;
      longDuration = parseInt(document.getElementById('longInput').value) || 15;
      isAutoFlow = document.getElementById('autoFlowToggle').checked;
      currentAlarm = document.getElementById('alarmSelect').value;

      localStorage.setItem('ll_pomo', pomoDuration);
      localStorage.setItem('ll_short', shortDuration);
      localStorage.setItem('ll_long', longDuration);
      localStorage.setItem('ll_auto', isAutoFlow);
      localStorage.setItem('ll_alarm', currentAlarm);

      toggleSettings();
      applyPreset(currentPreset);
    }

    const affirmations = [
      "You've got this!",
      "Focus on the present moment.",
      "One step at a time.",
      "Breathe in, breathe out, focus.",
      "Consistency is key.",
      "You are capable of amazing things.",
      "Progress over perfection."
    ];
    let affIndex = 0;
    const affDisplay = document.getElementById('affirmationDisplay');
    setInterval(() => {
      affDisplay.style.opacity = 0;
      setTimeout(() => {
        affIndex = (affIndex + 1) % affirmations.length;
        affDisplay.innerText = affirmations[affIndex];
        affDisplay.style.opacity = 1;
      }, 500);
    }, 10000);

    function loadTasks() {
      const saved = localStorage.getItem('learnersLandingTasks');
      if(saved) document.getElementById('taskList').innerHTML = saved;
    }

    function saveTasks() {
      const checkboxes = document.querySelectorAll('.task-check');
      checkboxes.forEach(cb => {
        if(cb.checked) cb.setAttribute('checked', 'checked');
        else cb.removeAttribute('checked');
      });
      localStorage.setItem('learnersLandingTasks', document.getElementById('taskList').innerHTML);
    }

    function addTask() {
      const input = document.getElementById('newTaskInput');
      const priority = document.getElementById('prioritySelect').value;
      if(input.value.trim() === '') return;

      const ul = document.getElementById('taskList');
      const li = document.createElement('li');
      li.innerHTML = `
        <span class='task-priority'>${priority}</span>
        <span class='task-text'>${input.value}</span>
        <input type='checkbox' class='task-check' onclick='this.parentElement.style.textDecoration = this.checked ? "line-through" : "none"; this.parentElement.style.opacity = this.checked ? "0.5" : "1"; setTimeout(saveTasks, 50);'>
        <button class='task-delete' onclick='this.parentElement.remove(); setTimeout(saveTasks, 50);' title='Delete'>✕</button>
      `;
      ul.appendChild(li);
      input.value = '';
      saveTasks();
    }

    const notepad = document.getElementById('sessionNotes');
    if(localStorage.getItem('learnersLandingNotes')) {
      notepad.value = localStorage.getItem('learnersLandingNotes');
    }
    function saveNotes() {
      localStorage.setItem('learnersLandingNotes', notepad.value);
    }

    const player = document.getElementById('ambientPlayer');
    function changeAudio() {
      player.src = document.getElementById('audioSelect').value;
      player.play();
    }
    function toggleAudio() {
      player.paused ? player.play() : player.pause();
    }
    function updateVolume() {
      player.volume = document.getElementById('volumeControl').value;
    }

    const backgrounds = [
      "https://images.pexels.com/photos/1624496/pexels-photo-1624496.jpeg?auto=compress&cs=tinysrgb&w=1600",
      "https://images.pexels.com/photos/3747463/pexels-photo-3747463.jpeg?auto=compress&cs=tinysrgb&w=1600",
      "https://images.pexels.com/photos/167699/pexels-photo-167699.jpeg?auto=compress&cs=tinysrgb&w=1600",
      "https://images.pexels.com/photos/155395/pexels-photo-155395.jpeg?auto=compress&cs=tinysrgb&w=1600"
    ];
    let bgIndex = 0;
    function changeBackground() {
      bgIndex = (bgIndex + 1) % backgrounds.length;
      document.getElementById('sessionsBg').style.backgroundImage = `url('${backgrounds[bgIndex]}')`;
    }

    updateDisplay();
    loadTasks();
    player.src = document.getElementById('audioSelect').value;
  }
//
